// Node.js HTTP Server with Express & TypeScript
import express from 'express';
const app = express();
app.use(express.json());

app.get('/health', (req, res) => {
  res.json({ status: 'UP', timestamp: new Date().toISOString() });
});
app.listen(8080);

-- PostgreSQL Transaction with Row Locking
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 'acc_1' AND balance >= 100;
UPDATE accounts SET balance = balance + 100 WHERE id = 'acc_2';
COMMIT;

// MongoDB Aggregation Pipeline
db.orders.aggregate([
  { $match: { status: 'completed' } },
  { $group: { _id: '$customerId', totalSpent: { $sum: '$amount' } } }
]);

// Password Hashing with Argon2 in Node.js
import argon2 from 'argon2';

const hash = await argon2.hash('hunterPassword123');
const isMatch = await argon2.verify(hash, 'hunterPassword123');

// Redis Cache-Aside Pattern in Node.js
async function getCachedUser(id) {
  const cached = await redis.get(`user:${id}`);
  if (cached) return JSON.parse(cached);
  const user = await db.users.findUnique({ where: { id } });
  await redis.setex(`user:${id}`, 300, JSON.stringify(user));
  return user;
}

